const base = (
  process.env.RENDER_EXTERNAL_URL ||
  process.env.PUBLIC_BASE_URL ||
  process.env.WEBAPP_URL ||
  process.env.WEB_APP_URL ||
  process.env.PUBLIC_URL ||
  ""
).replace(/\/+$/, "").replace(/\/app$/i, "");

export const cfg = {
  TELEGRAM_BOT_TOKEN: process.env.TELEGRAM_BOT_TOKEN || "",
  MONGODB_URI: process.env.MONGODB_URI || "",
  PORT: Number(process.env.PORT || 4000),
  PUBLIC_BASE_URL: base,
  ADMIN_TELEGRAM_IDS: String(process.env.ADMIN_TELEGRAM_IDS || "")
    .split(",")
    .map((v) => v.trim())
    .filter(Boolean),
  AI_TIMEOUT_MS: Number(process.env.AI_TIMEOUT_MS || 600000),
  AI_MAX_RETRIES: Number(process.env.AI_MAX_RETRIES || 2),
  CONCURRENCY: Number(process.env.CONCURRENCY || 20)
};

export function getMiniAppUrl(path = "") {
  const mini = cfg.PUBLIC_BASE_URL ? `${cfg.PUBLIC_BASE_URL}/app` : "";
  if (!mini) return "";
  const normalized = String(path || "").replace(/^\/+/, "");
  return normalized ? `${mini}?page=${encodeURIComponent(normalized)}` : mini;
}

db.js.content:
import { MongoClient } from "mongodb";
import { cfg } from "./config.js";
import { safeErr, nowIso } from "./utils.js";

let client = null;
let db = null;
let memoryStore = null;

function createMemoryStore() {
  const state = {
    users: new Map(),
    polls: new Map(),
    votes: new Map(),
    rewards: new Map(),
    memoryMessages: []
  };
  return {
    kind: "memory",
    state
  };
}

export async function connectDb() {
  if (!cfg.MONGODB_URI) {
    memoryStore = createMemoryStore();
    console.warn("[db] MONGODB_URI missing, using in-memory fallback");
    return null;
  }

  try {
    client = new MongoClient(cfg.MONGODB_URI, { ignoreUndefined: true });
    await client.connect();
    db = client.db();
    console.log("[db] connected", { mongo: true });
    await ensureIndexes();
    return db;
  } catch (err) {
    console.error("[db] connect failure", { operation: "connect", error: safeErr(err) });
    memoryStore = createMemoryStore();
    return null;
  }
}

async function ensureIndexes() {
  if (!db) return;
  try {
    await db.collection("users").createIndex({ telegramId: 1 }, { unique: true });
    await db.collection("votes").createIndex({ pollId: 1, telegramId: 1 }, { unique: true });
    await db.collection("polls").createIndex({ status: 1, endTime: 1 });
    await db.collection("rewards").createIndex({ telegramId: 1, status: 1 });
    await db.collection("memory_messages").createIndex({ telegramId: 1, ts: -1 });
  } catch (err) {
    console.error("[db] index failure", { operation: "ensureIndexes", error: safeErr(err) });
  }
}

export function getDbMode() {
  return db ? "mongo" : "memory";
}

export function getCollections() {
  if (db) {
    return {
      users: db.collection("users"),
      polls: db.collection("polls"),
      votes: db.collection("votes"),
      rewards: db.collection("rewards"),
      memoryMessages: db.collection("memory_messages")
    };
  }
  return memoryStore.state;
}

export async function saveMemoryMessage({ telegramId, chatId, role, text }) {
  const clean = {
    telegramId: String(telegramId || ""),
    chatId: String(chatId || ""),
    platform: "telegram",
    role: String(role || "user"),
    text: String(text || "").slice(0, 2000),
    ts: new Date()
  };

  if (db) {
    try {
      await db.collection("memory_messages").insertOne(clean);
    } catch (err) {
      console.error("[db] memory write failure", { collection: "memory_messages", operation: "insertOne", error: safeErr(err) });
    }
    return;
  }

  memoryStore.state.memoryMessages.push(clean);
  if (memoryStore.state.memoryMessages.length > 5000) {
    memoryStore.state.memoryMessages.shift();
  }
}

export async function getRecentMemory(telegramId, limit = 10) {
  const id = String(telegramId || "");
  if (db) {
    try {
      return await db.collection("memory_messages").find({ telegramId: id }).sort({ ts: -1 }).limit(limit).toArray();
    } catch (err) {
      console.error("[db] memory read failure", { collection: "memory_messages", operation: "find", error: safeErr(err) });
      return [];
    }
  }
  return memoryStore.state.memoryMessages.filter((m) => m.telegramId === id).slice(-limit).reverse();
}

export async function clearMemory(telegramId) {
  const id = String(telegramId || "");
  if (db) {
    try {
      await db.collection("memory_messages").deleteMany({ telegramId: id });
    } catch (err) {
      console.error("[db] memory clear failure", { collection: "memory_messages", operation: "deleteMany", error: safeErr(err) });
    }
    return;
  }
  memoryStore.state.memoryMessages = memoryStore.state.memoryMessages.filter((m) => m.telegramId !== id);
}

export function genId(prefix) {
  return `${prefix}_${Math.random().toString(36).slice(2, 10)}_${Date.now().toString(36)}`;
}

export function stampInsert(doc = {}) {
  return {
    ...doc,
    createdAt: new Date(),
    updatedAt: new Date()
  };
}

export function stampUpdate(doc = {}) {
  const next = { ...doc };
  delete next._id;
  delete next.createdAt;
  return {
    ...next,
    updatedAt: new Date()
  };
}

export function fallbackNow() {
  return nowIso();
}

utils.js.content:
export function safeErr(err) {
  return err?.response?.data?.error?.message || err?.response?.data?.message || err?.message || String(err);
}

export function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export function clampText(value, max = 280) {
  return String(value || "").trim().slice(0, max);
}

export function nowIso() {
  return new Date().toISOString();
}

server.js.content:
import express from "express";
import path from "node:path";
import fs from "node:fs";
import { fileURLToPath } from "node:url";
import { cfg } from "./lib/config.js";
import { safeErr } from "./lib/utils.js";
import { bootstrapTelegramUser } from "./services/auth.js";
import { createPoll, getPollById, getRewardsPageData, listPolls, submitVote } from "./services/polls.js";
import { getLeaderboard } from "./services/leaderboard.js";
import { claimRewardsForUser } from "./services/rewards.js";
import { getAdminStats, ensureAdmin } from "./services/admin.js";
import { getUserByTelegramId } from "./services/users.js";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const app = express();
let memLogAt = 0;

function authFromHeaders(req) {
  return {
    initData: String(req.headers["x-telegram-init-data"] || req.body?.initData || ""),
    fallbackUser: req.body?.user || null
  };
}

function sendIndex(res) {
  const file = path.join(__dirname, "..", "webapp", "dist", "index.html");
  if (fs.existsSync(file)) return res.sendFile(file);
  return res.status(200).send("Web app not built yet. Run npm run build:webapp.");
}

function maybeLogMemory() {
  const now = Date.now();
  if (now - memLogAt < 60000) return;
  memLogAt = now;
  const m = process.memoryUsage();
  console.log("[mem]", { rssMB: Math.round(m.rss / 1e6), heapUsedMB: Math.round(m.heapUsed / 1e6) });
}

app.use(express.json({ limit: "1mb" }));
app.use((req, _res, next) => {
  console.log("[http] request", { method: req.method, path: req.path });
  maybeLogMemory();
  next();
});

app.get("/health", (_req, res) => {
  res.json({ ok: true, service: "quickpoll-rewards" });
});

app.post("/api/auth/telegram", async (req, res) => {
  try {
    const { initData, fallbackUser } = authFromHeaders(req);
    const result = await bootstrapTelegramUser(initData, fallbackUser);
    if (!result.ok) {
      return res.status(401).json(result);
    }
    return res.json({ ok: true, user: result.user });
  } catch (err) {
    console.error("[api] auth failure", { error: safeErr(err) });
    return res.status(500).json({ ok: false, error: "AUTH_FAILED" });
  }
});

app.get("/api/me", async (req, res) => {
  try {
    const telegramId = String(req.query.telegramId || "");
    const user = await getUserByTelegramId(telegramId);
    return res.json({ ok: true, user });
  } catch (err) {
    console.error("[api] me failure", { error: safeErr(err) });
    return res.status(500).json({ ok: false, error: "ME_FAILED" });
  }
});

app.get("/api/polls", async (req, res) => {
  try {
    const activeOnly = String(req.query.activeOnly || "1") !== "0";
    const polls = await listPolls({ activeOnly });
    return res.json({ ok: true, polls });
  } catch (err) {
    console.error("[api] list polls failure", { error: safeErr(err) });
    return res.status(500).json({ ok: false, error: "POLLS_FAILED" });
  }
});

app.get("/api/polls/:pollId", async (req, res) => {
  try {
    const poll = await getPollById(req.params.pollId);
    if (!poll) return res.status(404).json({ ok: false, error: "POLL_NOT_FOUND" });
    return res.json({ ok: true, poll });
  } catch (err) {
    console.error("[api] poll detail failure", { error: safeErr(err) });
    return res.status(500).json({ ok: false, error: "POLL_DETAIL_FAILED" });
  }
});

app.post("/api/polls", async (req, res) => {
  try {
    const { initData, fallbackUser } = authFromHeaders(req);
    const auth = await bootstrapTelegramUser(initData, fallbackUser);
    if (!auth.ok) return res.status(401).json(auth);

    const poll = await createPoll({
      creator: auth.user,
      question: req.body?.question,
      options: req.body?.options || [],
      pollType: req.body?.pollType,
      rewardPoints: req.body?.rewardPoints,
      endTime: req.body?.endTime,
      correctOptionId: req.body?.correctOptionId
    });

    return res.json({ ok: true, poll });
  } catch (err) {
    console.error("[api] create poll failure", { error: safeErr(err) });
    return res.status(400).json({ ok: false, error: safeErr(err) });
  }
});

app.post("/api/polls/:pollId/vote", async (req, res) => {
  try {
    const { initData, fallbackUser } = authFromHeaders(req);
    const auth = await bootstrapTelegramUser(initData, fallbackUser);
    if (!auth.ok) return res.status(401).json(auth);

    const result = await submitVote({
      pollId: req.params.pollId,
      telegramId: auth.user.telegramId,
      optionId: req.body?.optionId
    });

    return res.json({ ok: true, ...result });
  } catch (err) {
    console.error("[api] vote failure", { error: safeErr(err) });
    return res.status(400).json({ ok: false, error: safeErr(err) });
  }
});

app.get("/api/leaderboard", async (req, res) => {
  try {
    const leaderboard = await getLeaderboard(Number(req.query.limit || 20));
    return res.json({ ok: true, leaderboard });
  } catch (err) {
    console.error("[api] leaderboard failure", { error: safeErr(err) });
    return res.status(500).json({ ok: false, error: "LEADERBOARD_FAILED" });
  }
});

app.get("/api/rewards", async (req, res) => {
  try {
    const telegramId = String(req.query.telegramId || "");
    const user = await getUserByTelegramId(telegramId);
    const details = await getRewardsPageData(telegramId);
    return res.json({ ok: true, user, ...details });
  } catch (err) {
    console.error("[api] rewards failure", { error: safeErr(err) });
    return res.status(500).json({ ok: false, error: "REWARDS_FAILED" });
  }
});

app.post("/api/rewards/claim", async (req, res) => {
  try {
    const { initData, fallbackUser } = authFromHeaders(req);
    const auth = await bootstrapTelegramUser(initData, fallbackUser);
    if (!auth.ok) return res.status(401).json(auth);

    const result = await claimRewardsForUser(auth.user.telegramId);
    return res.json({ ok: true, ...result });
  } catch (err) {
    console.error("[api] rewards claim failure", { error: safeErr(err) });
    return res.status(500).json({ ok: false, error: "CLAIM_FAILED" });
  }
});

app.get("/api/admin/stats", async (req, res) => {
  try {
    const telegramId = String(req.query.telegramId || "");
    const allowed = await ensureAdmin(telegramId);
    if (!allowed) return res.status(403).json({ ok: false, error: "FORBIDDEN" });
    const stats = await getAdminStats();
    return res.json({ ok: true, stats });
  } catch (err) {
    console.error("[api] admin stats failure", { error: safeErr(err) });
    return res.status(500).json({ ok: false, error: "ADMIN_FAILED" });
  }
});

const distDir = path.join(__dirname, "..", "webapp", "dist");
if (fs.existsSync(distDir)) {
  app.use("/app", express.static(distDir));
}

app.get("/app", (_req, res) => sendIndex(res));
app.get("/app/*splat", (_req, res) => sendIndex(res));
app.get("/", (_req, res) => res.redirect("/app"));

export async function startServer() {
  await new Promise((resolve) => {
    app.listen(cfg.PORT, () => {
      console.log("[http] server started", { port: cfg.PORT });
      resolve();
    });
  });
}

